"""Negative finding: the four defects the bundle was designed for ARE caught by the old bundle.

Each kernel below is defined inline and run through gate.check with laws OFF, so this
documents what bundle.yaml alone already rejects. Run: venv/bin/python scratch/classic_defects.py
"""
import sys
from pathlib import Path
sys.path.insert(0, str(Path(__file__).resolve().parent.parent))
import numpy as np
from gate import check

EPS = 1e-5

def no_centering(x):
    w = x.astype(np.float64); v = np.var(w, axis=-1, keepdims=True)
    return (w / np.sqrt(v + EPS)).astype(x.dtype)

def no_scaling(x):
    w = x.astype(np.float64)
    return (w - w.mean(-1, keepdims=True)).astype(x.dtype)

def sample_variance(x):
    w = x.astype(np.float64); c = w - w.mean(-1, keepdims=True)
    n = x.shape[-1]; v = (c * c).sum(-1, keepdims=True) / max(n - 1, 1)
    return (c / np.sqrt(v + EPS)).astype(x.dtype)

def eps_outside_sqrt(x):
    w = x.astype(np.float64); c = w - w.mean(-1, keepdims=True)
    v = (c * c).mean(-1, keepdims=True)
    return (c / (np.sqrt(v) + EPS)).astype(x.dtype)

def eps_outside_sqrt_large(x):
    # eps outside the root only matters when it is comparable to the std; 1e-5 vs std~5.8 is invisible
    w = x.astype(np.float64); c = w - w.mean(-1, keepdims=True)
    v = (c * c).mean(-1, keepdims=True)
    return (c / (np.sqrt(v) + 1e-2)).astype(x.dtype)

def mean_over_wrong_axis(x):
    w = x.astype(np.float64); c = w - w.mean(0, keepdims=True)
    v = (c * c).mean(-1, keepdims=True)
    return (c / np.sqrt(v + EPS)).astype(x.dtype)

def global_std(x):
    w = x.astype(np.float64); c = w - w.mean(-1, keepdims=True)
    v = (c * c).mean()
    return (c / np.sqrt(v + EPS)).astype(x.dtype)

for fn in (no_centering, no_scaling, sample_variance, eps_outside_sqrt, eps_outside_sqrt_large,
           mean_over_wrong_axis, global_std):
    v = check(fn, include_laws=False)
    d, r = v["declarative"], v["reference"]
    print(f"{fn.__name__:24s} declarative {d[0]}/{d[1]}  reference {r[0]}/{r[1]}   {d[2][:90]}")
EOF
venv/bin/python scratch/classic_defects.py
